
function playTitleMusic() {
  if (titleMusic.paused) {
    titleMusic.play().catch(() => {});
  }
}

function stopTitleMusic() {
  if (!titleMusic.paused) {
    titleMusic.pause();
    titleMusic.currentTime = 0;
  }
}

const fightMusic = new Audio('data:audio/mpeg;base64,');
fightMusic.loop = true;
fightMusic.volume = 0.5;

function playFightMusic() {
  if (fightMusic.paused) {
    fightMusic.currentTime = 0;
    fightMusic.play().catch(() => {});
  }
}

function stopFightMusic() {
  if (!fightMusic.paused) {
    fightMusic.pause();
    fightMusic.currentTime = 0;
  }
}
